-- 0001_initial.sql
--
-- Initial schema for the Script Workspace feature. See
-- specs/001-script-workspace/data-model.md for the entity definitions this
-- migration materialises.
--
-- Design notes:
--   * Identifiers are UUIDs generated by the database (pgcrypto's gen_random_uuid),
--     so no application path can invent or reuse an id.
--   * Title uniqueness is enforced on the normalized (lowercased, trimmed) title by a
--     database constraint, not only by application validation, so a race cannot produce
--     two identically titled scripts.
--   * A Script owns exactly one Conversation. The one-to-one relation is enforced by a
--     unique constraint on conversations.script_id plus the foreign keys below.
--   * Every child row cascades from its Script, so a confirmed delete removes the
--     conversation, messages, and versions together (FR-001d).

CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- ---------------------------------------------------------------------------
-- styles: the static catalogue. Seeded, never written by the application.
-- ---------------------------------------------------------------------------
CREATE TABLE styles (
  id            TEXT        PRIMARY KEY,
  name          TEXT        NOT NULL,
  description   TEXT        NOT NULL,
  guidance      TEXT        NOT NULL,
  -- Catalogue presentation order. spec.md's assumptions make the first catalogue
  -- entry the default for a new script, so the order is content, not creation time.
  display_order INTEGER     NOT NULL,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),

  CONSTRAINT styles_name_unique    UNIQUE (name),
  CONSTRAINT styles_name_not_blank CHECK (btrim(name) <> ''),
  CONSTRAINT styles_guidance_not_blank CHECK (btrim(guidance) <> ''),
  CONSTRAINT styles_display_order_unique UNIQUE (display_order)
);

-- ---------------------------------------------------------------------------
-- scripts: the document itself. The single source of truth for content.
-- ---------------------------------------------------------------------------
CREATE TABLE scripts (
  id            UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
  title         TEXT        NOT NULL,
  content       TEXT        NOT NULL DEFAULT '',
  style_id      TEXT        REFERENCES styles (id) ON DELETE RESTRICT,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at    TIMESTAMPTZ NOT NULL DEFAULT now(),

  -- Case-insensitive uniqueness on the trimmed title. A partial-free expression
  -- index is what makes the 409 title_taken path race-safe.
  CONSTRAINT scripts_title_length CHECK (char_length(btrim(title)) BETWEEN 1 AND 200),
  CONSTRAINT scripts_title_not_blank CHECK (btrim(title) <> '')
);

CREATE UNIQUE INDEX scripts_normalized_title_unique
  ON scripts (lower(btrim(title)));

-- The sidebar lists scripts by last modification, newest first (FR-002).
CREATE INDEX scripts_updated_at_desc_idx
  ON scripts (updated_at DESC);

-- ---------------------------------------------------------------------------
-- conversations: exactly one per script.
-- ---------------------------------------------------------------------------
CREATE TABLE conversations (
  id         UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
  script_id  UUID        NOT NULL REFERENCES scripts (id) ON DELETE CASCADE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),

  CONSTRAINT conversations_script_unique UNIQUE (script_id)
);

-- ---------------------------------------------------------------------------
-- messages: the conversation history, ordered by (created_at, id).
-- ---------------------------------------------------------------------------
CREATE TABLE messages (
  id              UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
  conversation_id UUID        NOT NULL REFERENCES conversations (id) ON DELETE CASCADE,
  role            TEXT        NOT NULL,
  content         TEXT        NOT NULL,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),

  CONSTRAINT messages_role_valid CHECK (role IN ('user', 'assistant'))
);

-- Messages created in the same millisecond keep a stable order via the id tiebreak.
CREATE INDEX messages_conversation_order_idx
  ON messages (conversation_id, created_at, id);

-- ---------------------------------------------------------------------------
-- script_versions: recoverable prior states. Immutable once written.
-- ---------------------------------------------------------------------------
CREATE TABLE script_versions (
  id         UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
  script_id  UUID        NOT NULL REFERENCES scripts (id) ON DELETE CASCADE,
  content    TEXT        NOT NULL,
  origin     TEXT        NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),

  CONSTRAINT script_versions_origin_valid CHECK (origin IN ('user', 'assistant'))
);

-- Newest-first lookup for the undo affordance (FR-020).
CREATE INDEX script_versions_script_order_idx
  ON script_versions (script_id, created_at DESC, id DESC);

-- A version is immutable: once written, its content and origin never change.
-- DELETE is left permitted so the ON DELETE CASCADE from a confirmed script
-- delete can remove history with the script (FR-001d).
CREATE FUNCTION script_versions_reject_update()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
  RAISE EXCEPTION 'script_versions rows are immutable';
END;
$$;

CREATE TRIGGER script_versions_immutable
  BEFORE UPDATE ON script_versions
  FOR EACH ROW EXECUTE FUNCTION script_versions_reject_update();
